  "cpu.h": "#ifndef CPU_H\n#define CPU_H\n\n#include <stdint.h>\n\n// The status register P, bit by bit.\n#define FLAG_C 0x01  // carry\n#define FLAG_Z 0x02  // zero\n#define FLAG_I 0x04  // interrupt disable\n#define FLAG_D 0x08  // decimal (stored, but the NES ignores it)\n#define FLAG_B 0x10  // break (only exists in copies of P pushed to the stack)\n#define FLAG_U 0x20  // unused, always 1\n#define FLAG_V 0x40  // overflow\n#define FLAG_N 0x80  // negative\n\ntypedef struct {\n    uint8_t a;        // accumulator\n    uint8_t x;        // index register X\n    uint8_t y;        // index register Y\n    uint8_t sp;       // stack pointer: the stack lives at 0x0100 + sp\n    uint8_t p;        // status flags\n    uint16_t pc;      // program counter: address of the next instruction\n    uint64_t cycles;  // CPU cycles since power-on\n} Cpu;\n\n// Power on: registers to their start values, PC from the reset vector.\nvoid cpu_reset(Cpu *cpu);\n\n// Run one instruction. Returns how many cycles it took.\nint cpu_step(Cpu *cpu);\n\n// Interrupt the CPU with an NMI (the PPU does this every frame).\nvoid cpu_nmi(Cpu *cpu);\n\n#endif\n",
  "bus.h": "#ifndef BUS_H\n#define BUS_H\n\n#include <stdint.h>\n\n// The CPU bus: every address the CPU can read or write.\nvoid bus_reset(void);\nuint8_t bus_read(uint16_t addr);\nvoid bus_write(uint16_t addr, uint8_t value);\n\n// Read a 16-bit little-endian value through the bus.\nuint16_t bus_read16(uint16_t addr);\n\n// Name of the part of the console an address reaches.\nconst char *bus_region(uint16_t addr);\n\n#endif\n",
  "cart.h": "#ifndef CART_H\n#define CART_H\n\n#include <stdint.h>\n\n// How the PPU's 2 KB of nametable memory appears in its four nametable slots.\ntypedef enum {\n    MIRROR_HORIZONTAL = 0,  // 2000 = 2400 and 2800 = 2C00 (for games that scroll up and down)\n    MIRROR_VERTICAL = 1,    // 2000 = 2800 and 2400 = 2C00 (for games that scroll sideways)\n} Mirroring;\n\n// What cart_load returns.\n#define CART_OK 0\n#define CART_NOT_INES -1            // the file does not start with \"NES\" and 1A\n#define CART_TOO_SHORT -2           // the file is shorter than its header says\n#define CART_UNSUPPORTED_MAPPER -3  // a mapper this emulator does not have yet\n#define CART_NO_MEMORY -4           // malloc failed\n\n// Read an iNES file that is already in memory. Returns one of the codes above.\nint cart_load(const uint8_t *data, long size);\n\n// What the header said.\nint cart_mapper(void);\nint cart_prg_banks(void);   // in 16 KB units\nint cart_chr_banks(void);   // in 8 KB units; 0 means 8 KB of CHR RAM instead\nMirroring cart_mirroring(void);\nint cart_has_battery(void);\n\n// The cartridge as the CPU sees it: 4020-FFFF.\nuint8_t cart_cpu_read(uint16_t addr);\nvoid cart_cpu_write(uint16_t addr, uint8_t value);\n\n// The cartridge as the PPU sees it: pattern tables at 0000-1FFF.\nuint8_t cart_ppu_read(uint16_t addr);\nvoid cart_ppu_write(uint16_t addr, uint8_t value);\n\n#endif\n",
  "ppu.h": "#ifndef PPU_H\n#define PPU_H\n\n#include <stdint.h>\n\n#define PPU_WIDTH 256\n#define PPU_HEIGHT 240\n\n// Power on: clear the PPU's memory and registers.\nvoid ppu_reset(void);\n\n// The PPU's own bus, 0000-3FFF:\n//   0000-1FFF pattern tables (the cartridge's CHR)\n//   2000-2FFF four nametables (2 KB of video RAM, mirrored), repeated up to 3EFF\n//   3F00-3F1F palette RAM, repeated up to 3FFF\nuint8_t ppu_read(uint16_t addr);\nvoid ppu_write(uint16_t addr, uint8_t value);\n\n// Row `row` (0-7) of tile `tile` in the pattern table at `table` (0x0000 or\n// 0x1000), as eight colour numbers 0-3, left to right.\nvoid ppu_tile_row(uint16_t table, uint8_t tile, int row, uint8_t out[8]);\n\n// The eight registers the CPU sees at 2000-2007. reg is 0 to 7.\nuint8_t ppu_register_read(int reg);\nvoid ppu_register_write(int reg, uint8_t value);\n\n// Advance the PPU by one dot.\nvoid ppu_tick(void);\n\n// Each returns 1 once, the first time it is asked after the event happened.\nint ppu_take_nmi(void);    // the PPU wants to interrupt the CPU\nint ppu_take_frame(void);  // a frame has been finished\n\n// Where the PPU is in the frame: scanline 0-261, dot 0-340.\nint ppu_scanline(void);\nint ppu_dot(void);\n\n// The finished picture: 256 x 240 pixels, each 0x00RRGGBB.\nconst uint32_t *ppu_pixels(void);\n\n#endif\n",
