   "harness": "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include \"cart.h\"\n// Builds a small iNES file in memory for the tests.\nstatic uint8_t rom_file[16 + 512 + 2 * 0x4000 + 0x2000];\n\nstatic long make_rom(int prg_banks, int chr_banks, uint8_t flags6, uint8_t flags7) {\n    memset(rom_file, 0, sizeof rom_file);\n    memcpy(rom_file, \"NES\\x1A\", 4);\n    rom_file[4] = (uint8_t)prg_banks;\n    rom_file[5] = (uint8_t)chr_banks;\n    rom_file[6] = flags6;\n    rom_file[7] = flags7;\n    long trainer = (flags6 & 0x04) ? 512 : 0;\n    uint8_t *p = rom_file + 16 + trainer;\n    for (long i = 0; i < prg_banks * 0x4000L; i++) *p++ = (uint8_t)(i * 7 + (i >> 8));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) *p++ = (uint8_t)(0xA0 ^ i ^ (i >> 4));\n    return 16 + trainer + prg_banks * 0x4000L + chr_banks * 0x2000L;\n}\n\nstatic uint8_t *read_file(const char *name, long *size) {\n    FILE *f = fopen(name, \"rb\");\n    if (!f) return NULL;\n    fseek(f, 0, SEEK_END);\n    *size = ftell(f);\n    fseek(f, 0, SEEK_SET);\n    uint8_t *data = malloc(*size);\n    if (data && fread(data, 1, *size, f) != (size_t)*size) { free(data); data = NULL; }\n    fclose(f);\n    return data;\n}\n\nstatic void show(int r) {\n    printf(\"result %d\", r);\n    if (r == CART_OK) {\n        printf(\": mapper %d, PRG %d, CHR %d, %s mirroring, battery %d\", cart_mapper(), cart_prg_banks(), cart_chr_banks(),\n               cart_mirroring() == MIRROR_VERTICAL ? \"vertical\" : \"horizontal\", cart_has_battery());\n    }\n    printf(\"\\n\");\n}\n\nint main(void) {\n    int t = 0;\n    if (scanf(\"%d\", &t) != 1) return 1;\n    if (t == 1) {\n        show(cart_load(rom_file, make_rom(1, 1, 0x01, 0x00)));\n        show(cart_load(rom_file, make_rom(2, 0, 0x02, 0x00)));\n    }\n    if (t == 2) {\n        show(cart_load(rom_file, make_rom(1, 1, 0x10, 0x00)));\n        show(cart_load(rom_file, make_rom(1, 1, 0x40, 0x00)));\n        show(cart_load(rom_file, make_rom(1, 1, 0x00, 0x40)));\n        show(cart_load(rom_file, make_rom(1, 1, 0x11, 0x40)));\n    }\n    if (t == 3) {\n        long size = make_rom(1, 1, 0, 0);\n        show(cart_load(rom_file, 10));\n        rom_file[3] = 0x1B;\n        show(cart_load(rom_file, size));\n        size = make_rom(1, 1, 0, 0);\n        rom_file[4] = 2;\n        show(cart_load(rom_file, size));\n    }\n    if (t == 4) {\n        long size = make_rom(1, 1, 0x04, 0x00);\n        show(cart_load(rom_file, size));\n        show(cart_load(rom_file, size - 1));\n    }\n    return 0;\n}\n",
