   "solution": {
    "cart.c": "#include <stdlib.h>\n#include <string.h>\n#include \"cart.h\"\n\n// What the header says.\nstatic int mapper;\nstatic int prg_banks;\nstatic int chr_banks;\nstatic Mirroring mirroring;\nstatic int battery;\n\n// The cartridge's memory.\nstatic uint8_t *prg = NULL;      // program ROM: prg_banks * 16 KB\nstatic long prg_size = 0;\nstatic uint8_t *chr = NULL;      // pattern tables: CHR ROM, or 8 KB of CHR RAM\nstatic int chr_is_ram = 0;\nstatic uint8_t prg_ram[0x2000];  // 6000-7FFF\n\nint cart_load(const uint8_t *data, long size) {\n    if (size < 16) {\n        return CART_TOO_SHORT;\n    }\n    if (data[0] != 'N' || data[1] != 'E' || data[2] != 'S' || data[3] != 0x1A) {\n        return CART_NOT_INES;\n    }\n    int new_prg_banks = data[4];\n    int new_chr_banks = data[5];\n    uint8_t flags6 = data[6];\n    uint8_t flags7 = data[7];\n    long trainer = (flags6 & 0x04) ? 512 : 0;\n    long needed = 16 + trainer + new_prg_banks * 0x4000L + new_chr_banks * 0x2000L;\n    if (size < needed) {\n        return CART_TOO_SHORT;\n    }\n    int new_mapper = (flags7 & 0xF0) | (flags6 >> 4);\n    if (new_mapper != 0) {\n        return CART_UNSUPPORTED_MAPPER;\n    }\n\n    // Copy the ROMs into memory of our own, replacing any earlier cartridge.\n    long new_prg_size = new_prg_banks * 0x4000L;\n    long chr_size = new_chr_banks ? new_chr_banks * 0x2000L : 0x2000L;\n    uint8_t *new_prg = malloc(new_prg_size);\n    uint8_t *new_chr = malloc(chr_size);\n    if (new_prg == NULL || new_chr == NULL) {\n        free(new_prg);\n        free(new_chr);\n        return CART_NO_MEMORY;\n    }\n    const uint8_t *rom = data + 16 + trainer;\n    memcpy(new_prg, rom, new_prg_size);\n    if (new_chr_banks) {\n        memcpy(new_chr, rom + new_prg_size, chr_size);\n    } else {\n        memset(new_chr, 0, chr_size);\n    }\n    free(prg);\n    free(chr);\n    prg = new_prg;\n    prg_size = new_prg_size;\n    chr = new_chr;\n    chr_is_ram = new_chr_banks == 0;\n    memset(prg_ram, 0, sizeof prg_ram);\n\n    mapper = new_mapper;\n    prg_banks = new_prg_banks;\n    chr_banks = new_chr_banks;\n    mirroring = (flags6 & 0x01) ? MIRROR_VERTICAL : MIRROR_HORIZONTAL;\n    battery = (flags6 & 0x02) != 0;\n    return CART_OK;\n}\n\nint cart_mapper(void) { return mapper; }\nint cart_prg_banks(void) { return prg_banks; }\nint cart_chr_banks(void) { return chr_banks; }\nMirroring cart_mirroring(void) { return mirroring; }\nint cart_has_battery(void) { return battery; }\n\nuint8_t cart_cpu_read(uint16_t addr) {\n    if (addr >= 0x6000 && addr < 0x8000) {\n        return prg_ram[addr - 0x6000];\n    }\n    if (addr >= 0x8000 && prg_size > 0) {\n        return prg[(addr - 0x8000) % prg_size];\n    }\n    return 0;\n}\n\nvoid cart_cpu_write(uint16_t addr, uint8_t value) {\n    if (addr >= 0x6000 && addr < 0x8000) {\n        prg_ram[addr - 0x6000] = value;\n    }\n}\n\nuint8_t cart_ppu_read(uint16_t addr) {\n    if (chr == NULL) {\n        return 0;\n    }\n    return chr[addr & 0x1FFF];\n}\n\nvoid cart_ppu_write(uint16_t addr, uint8_t value) {\n    if (chr != NULL && chr_is_ram) {\n        chr[addr & 0x1FFF] = value;\n    }\n}\n"
   },
   "harness": "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include \"cart.h\"\n// Builds a small iNES file in memory for the tests.\nstatic uint8_t rom_file[16 + 512 + 2 * 0x4000 + 0x2000];\n\nstatic long make_rom(int prg_banks, int chr_banks, uint8_t flags6, uint8_t flags7) {\n    memset(rom_file, 0, sizeof rom_file);\n    memcpy(rom_file, \"NES\\x1A\", 4);\n    rom_file[4] = (uint8_t)prg_banks;\n    rom_file[5] = (uint8_t)chr_banks;\n    rom_file[6] = flags6;\n    rom_file[7] = flags7;\n    long trainer = (flags6 & 0x04) ? 512 : 0;\n    uint8_t *p = rom_file + 16 + trainer;\n    for (long i = 0; i < prg_banks * 0x4000L; i++) *p++ = (uint8_t)(i * 7 + (i >> 8));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) *p++ = (uint8_t)(0xA0 ^ i ^ (i >> 4));\n    return 16 + trainer + prg_banks * 0x4000L + chr_banks * 0x2000L;\n}\n\nstatic uint8_t *read_file(const char *name, long *size) {\n    FILE *f = fopen(name, \"rb\");\n    if (!f) return NULL;\n    fseek(f, 0, SEEK_END);\n    *size = ftell(f);\n    fseek(f, 0, SEEK_SET);\n    uint8_t *data = malloc(*size);\n    if (data && fread(data, 1, *size, f) != (size_t)*size) { free(data); data = NULL; }\n    fclose(f);\n    return data;\n}\n\nint main(void) {\n    int t = 0;\n    if (scanf(\"%d\", &t) != 1) return 1;\n    if (t == 1) {\n        printf(\"load %d\\n\", cart_load(rom_file, make_rom(1, 1, 0, 0)));\n        printf(\"%02X %02X %02X %02X\\n\", cart_cpu_read(0x8000), cart_cpu_read(0x8123), cart_cpu_read(0xC123), cart_cpu_read(0xFFFF));\n    }\n    if (t == 2) {\n        printf(\"load %d\\n\", cart_load(rom_file, make_rom(2, 1, 0, 0)));\n        printf(\"%02X %02X %02X %02X\\n\", cart_cpu_read(0x8000), cart_cpu_read(0x8123), cart_cpu_read(0xC123), cart_cpu_read(0xFFFF));\n    }\n    if (t == 3) {\n        printf(\"load %d\\n\", cart_load(rom_file, make_rom(1, 1, 0, 0)));\n        cart_cpu_write(0x6000, 0x11);\n        cart_cpu_write(0x7FFF, 0x22);\n        cart_cpu_write(0x8000, 0x99);\n        printf(\"%02X %02X %02X %02X\\n\", cart_cpu_read(0x6000), cart_cpu_read(0x7FFF), cart_cpu_read(0x6001), cart_cpu_read(0x8000));\n    }\n    if (t == 4) {\n        printf(\"load %d\\n\", cart_load(rom_file, make_rom(1, 1, 0, 0)));\n        printf(\"CHR ROM: %02X %02X %02X\", cart_ppu_read(0x0000), cart_ppu_read(0x0011), cart_ppu_read(0x1FFF));\n        cart_ppu_write(0x0000, 0x55);\n        printf(\" after a write: %02X\\n\", cart_ppu_read(0x0000));\n        printf(\"load %d\\n\", cart_load(rom_file, make_rom(1, 0, 0, 0)));\n        printf(\"CHR RAM: %02X\", cart_ppu_read(0x0000));\n        cart_ppu_write(0x0000, 0x55);\n        cart_ppu_write(0x1FFF, 0x66);\n        printf(\" after writes: %02X %02X\\n\", cart_ppu_read(0x0000), cart_ppu_read(0x1FFF));\n    }\n    if (t == 5) {\n        printf(\"load %d\\n\", cart_load(rom_file, make_rom(1, 1, 0, 0)));\n        uint8_t before = cart_cpu_read(0x8123);\n        printf(\"mapper 1: load %d\\n\", cart_load(rom_file, make_rom(1, 1, 0x10, 0)));\n        printf(\"the first cartridge is still there: %s\\n\", cart_cpu_read(0x8123) == before ? \"yes\" : \"no\");\n        long size = make_rom(2, 1, 0, 0);\n        rom_file[16 + 0x123] = 0xEE;\n        printf(\"load %d\\n\", cart_load(rom_file, size));\n        printf(\"the new one replaced it: %02X\\n\", cart_cpu_read(0x8123));\n    }\n    if (t == 6) {\n        long size = 0;\n        uint8_t *data = read_file(\"nestest.nes\", &size);\n        int r = cart_load(data, size);\n        printf(\"nestest: load %d, reset vector %02X%02X\\n\", r, cart_cpu_read(0xFFFD), cart_cpu_read(0xFFFC));\n        free(data);\n    }\n    return 0;\n}\n",
