   "main": "// Opcode's PPU register monitor. Provided by the course.\n// Commands (numbers in hex), like the CPU writing to 2000-2007:\n//   w REG VALUE  write VALUE to register REG (0-7), with ppu_register_write\n//   r REG        read register REG, with ppu_register_read\n//   p ADDR       peek at the PPU's memory directly, with ppu_read\n#include <stdio.h>\n#include <stdlib.h>\n#include <stdint.h>\n#include \"cart.h\"\n#include \"ppu.h\"\n\nstatic uint8_t *read_file(const char *name, long *size) {\n    FILE *f = fopen(name, \"rb\");\n    if (!f) return NULL;\n    fseek(f, 0, SEEK_END);\n    *size = ftell(f);\n    fseek(f, 0, SEEK_SET);\n    uint8_t *data = malloc(*size);\n    if (data && fread(data, 1, *size, f) != (size_t)*size) { free(data); data = NULL; }\n    fclose(f);\n    return data;\n}\n\n// Read game.nes and plug it in. Prints a message and returns 0 on failure.\nstatic int plug_in_cartridge(void) {\n    long size = 0;\n    uint8_t *data = read_file(\"game.nes\", &size);\n    if (!data) {\n        printf(\"Could not read the cartridge file.\\n\");\n        return 0;\n    }\n    int r = cart_load(data, size);\n    free(data);\n    if (r == CART_UNSUPPORTED_MAPPER) {\n        printf(\"This cartridge uses mapper %d, which your emulator does not have yet.\\n\", cart_mapper());\n        return 0;\n    }\n    if (r != CART_OK) {\n        printf(\"cart_load could not read this cartridge (it returned %d).\\n\", r);\n        return 0;\n    }\n    return 1;\n}\n\nstatic const char *NAMES[8] = { \"PPUCTRL\", \"PPUMASK\", \"PPUSTATUS\", \"OAMADDR\", \"OAMDATA\", \"PPUSCROLL\", \"PPUADDR\", \"PPUDATA\" };\n\nint main(void) {\n    if (!plug_in_cartridge()) return 1;\n    ppu_reset();\n    char cmd;\n    unsigned a, v;\n    while (scanf(\" %c\", &cmd) == 1) {\n        if (cmd == 'w' && scanf(\"%x %x\", &a, &v) == 2 && a < 8) {\n            ppu_register_write((int)a, (uint8_t)v);\n            printf(\"write %02X to %s\\n\", v & 0xFF, NAMES[a]);\n        } else if (cmd == 'r' && scanf(\"%x\", &a) == 1 && a < 8) {\n            printf(\"read  %02X from %s\\n\", ppu_register_read((int)a), NAMES[a]);\n        } else if (cmd == 'p' && scanf(\"%x\", &a) == 1) {\n            printf(\"peek  %04X = %02X\\n\", a & 0x3FFF, ppu_read((uint16_t)a));\n        } else {\n            printf(\"I did not understand that command.\\n\");\n            return 1;\n        }\n    }\n    return 0;\n}\n",
