   "harness": "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include \"bus.h\"\n#include \"cart.h\"\n#include \"ppu.h\"\n// Builds a small iNES file in memory for the tests.\nstatic uint8_t rom_file[16 + 512 + 2 * 0x4000 + 0x2000];\n\nstatic long make_rom(int prg_banks, int chr_banks, uint8_t flags6, uint8_t flags7) {\n    memset(rom_file, 0, sizeof rom_file);\n    memcpy(rom_file, \"NES\\x1A\", 4);\n    rom_file[4] = (uint8_t)prg_banks;\n    rom_file[5] = (uint8_t)chr_banks;\n    rom_file[6] = flags6;\n    rom_file[7] = flags7;\n    long trainer = (flags6 & 0x04) ? 512 : 0;\n    uint8_t *p = rom_file + 16 + trainer;\n    for (long i = 0; i < prg_banks * 0x4000L; i++) *p++ = (uint8_t)(i * 7 + (i >> 8));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) *p++ = (uint8_t)(0xA0 ^ i ^ (i >> 4));\n    return 16 + trainer + prg_banks * 0x4000L + chr_banks * 0x2000L;\n}\n\nstatic uint8_t *read_file(const char *name, long *size) {\n    FILE *f = fopen(name, \"rb\");\n    if (!f) return NULL;\n    fseek(f, 0, SEEK_END);\n    *size = ftell(f);\n    fseek(f, 0, SEEK_SET);\n    uint8_t *data = malloc(*size);\n    if (data && fread(data, 1, *size, f) != (size_t)*size) { free(data); data = NULL; }\n    fclose(f);\n    return data;\n}\n\nint main(void) {\n    int t = 0;\n    if (scanf(\"%d\", &t) != 1) return 1;\n    cart_load(rom_file, make_rom(1, 0, 0x01, 0));\n    bus_reset();\n    ppu_reset();\n    if (t == 1) {\n        bus_write(0x2006, 0x3F); bus_write(0x2006, 0x00); bus_write(0x2007, 0x2A);\n        bus_write(0x3FFE, 0x21); bus_write(0x3FFE, 0x08); bus_write(0x3FFF, 0x33);\n        printf(\"3F00=%02X 2108=%02X\\n\", ppu_read(0x3F00), ppu_read(0x2108));\n    }\n    if (t == 2) {\n        bus_write(0x2003, 0x10); bus_write(0x2004, 0xAA); bus_write(0x2004, 0xBB);\n        bus_write(0x2003, 0x10);\n        uint8_t a = bus_read(0x2004), b = bus_read(0x2004);\n        bus_write(0x2003, 0x11);\n        printf(\"OAM: %02X %02X %02X\\n\", a, b, bus_read(0x2004));\n    }\n    if (t == 3) {\n        bus_write(0x2005, 0x12);\n        bus_write(0x2006, 0x34);\n        bus_write(0x2007, 0x5A);\n        printf(\"after one PPUSCROLL write, PPUADDR took the low byte: 0034=%02X\\n\", ppu_read(0x0034));\n        bus_read(0x2002);\n        bus_write(0x2006, 0x20); bus_write(0x2006, 0x10); bus_write(0x2007, 0x6B);\n        printf(\"after reading PPUSTATUS, both bytes again: 2010=%02X\\n\", ppu_read(0x2010));\n    }\n    if (t == 4) {\n        bus_write(0x0001, 0x77);\n        printf(\"RAM %02X, cartridge %02X %02X\\n\", bus_read(0x0801), bus_read(0x8000), bus_read(0xC123));\n    }\n    return 0;\n}\n",
