   "main": "// Opcode's PPU timeline. Provided by the course.\n// It ticks your PPU through two frames with NMIs turned on, and prints\n// every moment something happens.\n// Program input: the value written to PPUCTRL first (default 80: NMI on).\n#include <stdio.h>\n#include <stdlib.h>\n#include <stdint.h>\n#include \"cart.h\"\n#include \"ppu.h\"\n\nstatic uint8_t *read_file(const char *name, long *size) {\n    FILE *f = fopen(name, \"rb\");\n    if (!f) return NULL;\n    fseek(f, 0, SEEK_END);\n    *size = ftell(f);\n    fseek(f, 0, SEEK_SET);\n    uint8_t *data = malloc(*size);\n    if (data && fread(data, 1, *size, f) != (size_t)*size) { free(data); data = NULL; }\n    fclose(f);\n    return data;\n}\n\n// Read game.nes and plug it in. Prints a message and returns 0 on failure.\nstatic int plug_in_cartridge(void) {\n    long size = 0;\n    uint8_t *data = read_file(\"game.nes\", &size);\n    if (!data) {\n        printf(\"Could not read the cartridge file.\\n\");\n        return 0;\n    }\n    int r = cart_load(data, size);\n    free(data);\n    if (r == CART_UNSUPPORTED_MAPPER) {\n        printf(\"This cartridge uses mapper %d, which your emulator does not have yet.\\n\", cart_mapper());\n        return 0;\n    }\n    if (r != CART_OK) {\n        printf(\"cart_load could not read this cartridge (it returned %d).\\n\", r);\n        return 0;\n    }\n    return 1;\n}\n\nint main(void) {\n    if (!plug_in_cartridge()) return 1;\n    ppu_reset();\n    unsigned ctrl = 0x80;\n    if (scanf(\"%x\", &ctrl) != 1) ctrl = 0x80;\n    ppu_register_write(0, (uint8_t)ctrl);\n    printf(\"PPUCTRL = %02X\\n\", ctrl & 0xFF);\n    long dots = 0;\n    int frames = 0;\n    while (frames < 2 && dots < 400000) {\n        int sl = ppu_scanline(), d = ppu_dot();\n        ppu_tick();\n        dots++;\n        if (ppu_take_nmi()) printf(\"dot %6ld  (scanline %3d, dot %3d): NMI\\n\", dots, sl, d);\n        if (ppu_take_frame()) {\n            frames++;\n            printf(\"dot %6ld  (scanline %3d, dot %3d): frame %d finished\\n\", dots, sl, d, frames);\n        }\n        if (sl == 250 && d == 0) {\n            printf(\"dot %6ld  (scanline 250): PPUSTATUS reads %02X\", dots, ppu_register_read(2));\n            printf(\", then %02X\\n\", ppu_register_read(2));\n        }\n    }\n    printf(\"Two frames took %ld dots.\\n\", dots);\n    return 0;\n}\n",
